window.__ModuleLoader__.load({
 id:"@deepseek-ai/dsh-client-ui-code-graph",
 factory:(require)=>{
  const React=require("react"),jsx=require("react/jsx-runtime");
  const css=`.dshGraph{height:100%;min-height:0;display:grid;grid-template-columns:250px minmax(0,1fr);background:var(--dsw-alias-bg-base);color:var(--dsw-alias-label-primary)}.dshGraphRail{min-height:0;overflow:auto;border-right:1px solid var(--dsw-alias-border-l1);padding:12px;background:var(--dsw-specific-sidebar-fill)}.dshGraphTitle{font-size:15px;font-weight:650;margin-bottom:4px}.dshGraphHint{font-size:11px;line-height:17px;color:var(--dsw-alias-label-tertiary);margin-bottom:12px}.dshGraphTool{width:100%;text-align:left;border:0;border-radius:7px;padding:8px 9px;background:transparent;color:var(--dsw-alias-label-secondary);cursor:pointer}.dshGraphTool:hover,.dshGraphTool[data-active=true]{background:var(--dsw-alias-interactive-bg-hover);color:var(--dsw-alias-label-primary)}.dshGraphMain{min-width:0;min-height:0;overflow:auto;padding:18px}.dshGraphBar{display:flex;gap:8px;margin-bottom:14px}.dshGraphBar input{min-width:0;flex:1;border:1px solid var(--dsw-alias-border-l2);border-radius:8px;background:var(--dsw-alias-bg-layer-1);color:inherit;padding:8px 10px}.dshGraphBar button{border:0;border-radius:8px;background:var(--dsw-alias-brand-primary);color:white;padding:0 14px;cursor:pointer}.dshGraphCards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px}.dshGraphCard{border:1px solid var(--dsw-alias-border-l1);border-radius:10px;background:var(--dsw-alias-bg-layer-1);padding:12px}.dshGraphCard strong{display:block;font:600 13px ui-monospace,Consolas,monospace;color:var(--dsw-alias-brand-primary);overflow-wrap:anywhere}.dshGraphMeta{margin-top:6px;font-size:11px;color:var(--dsw-alias-label-tertiary);line-height:17px}.dshGraphEmpty{padding:36px;text-align:center;color:var(--dsw-alias-label-tertiary)}@media(max-width:760px){.dshGraph{grid-template-columns:1fr}.dshGraphRail{max-height:170px;border-right:0;border-bottom:1px solid var(--dsw-alias-border-l1)}}`;
  function installCss(){if(document.querySelector("style[data-dsh-code-graph]"))return;const s=document.createElement("style");s.dataset.dshCodeGraph="";s.textContent=css;document.head.appendChild(s)}
  const tools=[["symbols","符号列表"],["read","读取符号"],["references","查找引用"],["callers","调用者"],["callees","被调用者"],["chain","调用链"],["deps","文件依赖"],["blast","影响面"]];

  function CodeGraphView({sessionId,useSessions}){
   const cwd=useSessions(s=>s.byId[sessionId]?.cwd);const [tool,setTool]=React.useState("symbols"),[query,setQuery]=React.useState(""),[graph,setGraph]=React.useState({symbols:[],references:[],calls:[],deps:[]}),[selected,setSelected]=React.useState(""),[status,setStatus]=React.useState("选择“扫描”建立工作区只读图谱");
   const scan=async()=>{setStatus("正在由 Rust Host 建立源码图谱…");try{const response=await fetch(`/__dsh-preview/code-graph?sessionId=${encodeURIComponent(sessionId)}`);const next=await response.json();if(!response.ok)throw new Error(next.message||next.error||`HTTP ${response.status}`);setGraph(next);setStatus(`${next.files} 个源码文件 · ${next.symbols.length} 个符号 · ${next.references.length} 个引用 · ${next.engine}${next.truncated?" · 结果已截断":""}`);globalThis.__DSH_CODE_GRAPH_STATUS__={sessionId,files:next.files,symbols:next.symbols.length,references:next.references.length,engine:next.engine,time:Date.now()}}catch(e){setStatus("扫描失败："+(e instanceof Error?e.message:String(e)))}};
   let rows=graph.symbols;if(tool==="references")rows=graph.references;if(tool==="callers")rows=graph.calls.filter(row=>!selected||row.target===selected);if(tool==="callees")rows=graph.calls.filter(row=>!selected||row.source===selected);if(tool==="chain")rows=graph.calls;if(tool==="deps")rows=graph.deps;if(tool==="blast"){const targets=new Set(graph.calls.filter(row=>!selected||row.source===selected||row.target===selected).flatMap(row=>[row.source,row.target]));rows=[...graph.symbols.filter(row=>targets.has(row.id)),...graph.calls.filter(row=>targets.has(row.source)||targets.has(row.target))]}const filtered=rows.filter(r=>!query||r.name.toLowerCase().includes(query.toLowerCase())||r.path.toLowerCase().includes(query.toLowerCase()));const shown=filtered;
   return jsx.jsxs("div",{className:"dshGraph",children:[jsx.jsxs("aside",{className:"dshGraphRail",children:[jsx.jsx("div",{className:"dshGraphTitle",children:"代码图谱"}),jsx.jsx("div",{className:"dshGraphHint",children:"工作区符号、引用、调用与依赖关系；扫描严格只读。先选择一个符号可限定调用者、被调用者和影响面。"}),tools.map(([id,label])=>jsx.jsx("button",{className:"dshGraphTool","data-active":tool===id||void 0,onClick:()=>setTool(id),children:label},id))]}),jsx.jsxs("main",{className:"dshGraphMain",children:[jsx.jsxs("div",{className:"dshGraphBar",children:[jsx.jsx("input",{value:query,placeholder:"搜索符号或文件",onChange:e=>setQuery(e.target.value)}),jsx.jsx("button",{onClick:scan,children:"扫描"})]}),jsx.jsx("div",{className:"dshGraphHint",children:selected?`${status} · 已选择 ${graph.symbols.find(row=>row.id===selected)?.name||selected}`:status}),shown.length?jsx.jsx("div",{className:"dshGraphCards",children:shown.slice(0,500).map((row,index)=>jsx.jsxs("article",{className:"dshGraphCard",onClick:()=>row.id&&setSelected(row.id),children:[jsx.jsx("strong",{children:row.name}),jsx.jsxs("div",{className:"dshGraphMeta",children:[row.kind," · ",row.path,":",row.line,jsx.jsxs("div",{children:["视图：",tools.find(x=>x[0]===tool)?.[1]]})]})]},(row.id||row.source+row.target||row.path)+index))}):jsx.jsx("div",{className:"dshGraphEmpty",children:graph.symbols.length?"当前条件没有关系结果":"尚未建立图谱"})]})]})
  }
  function apply(ctx){installCss();ctx.slots.inject("conversation.view",()=>ctx.slots.register({name:"conversation.view",id:"code-graph",order:20,label:"代码图谱",inject:(sessionId)=>({sessionId})},CodeGraphView))}
  return {apply,inject:["slots","sessions"]}
 }
});
